@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <div class="board-loading">
        <p>Loading board…</p>
    </div>
}
else if (errorMessage is not null)
{
    <div class="board-error">
        <p>⚠️ @errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    @* Stats bar *@
    <div class="board-stats">
        <div class="stat">
            <span class="stat-value">@allTasks.Count</span>
            <span class="stat-label">Total</span>
        </div>
        <div class="stat">
            <span class="stat-value">@todoTasks.Count</span>
            <span class="stat-label">To Do</span>
        </div>
        <div class="stat">
            <span class="stat-value">@inProgressTasks.Count</span>
            <span class="stat-label">In Progress</span>
        </div>
        <div class="stat">
            <span class="stat-value">@doneTasks.Count</span>
            <span class="stat-label">Done</span>
        </div>
        <div class="stat stat-overdue">
            <span class="stat-value">@overdueTasks.Count</span>
            <span class="stat-label">Overdue</span>
        </div>
    </div>

    @* Search bar *@
    <div class="board-search">
        <input type="text"
               placeholder="Search tasks by title…"
               @bind="searchText"
               @bind:event="oninput" />
    </div>

    @* Kanban columns *@
    <div class="board-columns">
        <KanbanColumn ColumnName="To Do"
                      Tasks="FilteredTasks(todoTasks)"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRight="id => MoveTask(id, \"In Progress\")"
                      OnTaskCreated="formData => CreateTask(formData, \"To Do\")" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="FilteredTasks(inProgressTasks)"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeft="id => MoveTask(id, \"To Do\")"
                      OnMoveRight="id => MoveTask(id, \"Done\")"
                      OnTaskCreated="formData => CreateTask(formData, \"In Progress\")" />

        <KanbanColumn ColumnName="Done"
                      Tasks="FilteredTasks(doneTasks)"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="id => MoveTask(id, \"In Progress\")"
                      OnTaskCreated="formData => CreateTask(formData, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == "Done").ToList();
    private List<TaskItem> overdueTasks => allTasks.Where(t => t.DueDate < DateTime.Today && t.Status != "Done").ToList();

    private List<TaskItem> FilteredTasks(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;

        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.First(t => t.Id == taskId);
            allTasks = allTasks.Select(t => t.Id == taskId ? task with { Status = newStatus } : t).ToList();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task CreateTask((string Title, string Assignee, string Priority, DateTime DueDate) formData, string status)
    {
        var created = await TaskService.CreateTaskAsync(formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
        allTasks.Add(created with { Status = status });
    }
}

